const {authenticate}=require('./interna')._internals;
const HTML="<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <base href=\"/\">\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>CellTech Panamby | Sistema Interno</title>\n  <meta name=\"robots\" content=\"noindex,nofollow\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css\">\n  <link rel=\"stylesheet\" href=\"./funcionario.css?v=20260929-leads2\">\n</head>\n<body>\n<section id=\"loginScreen\" class=\"login-screen\">\n  <button id=\"loginThemeToggle\" class=\"theme-toggle login-theme-toggle\" type=\"button\" aria-label=\"Alternar tema\" title=\"Alternar tema\"><i class=\"fa-solid fa-moon\"></i></button>\n  <form id=\"loginForm\" class=\"login-card\">\n    <div class=\"brand\">CellTech <span>Panamby</span></div>\n    <h1>Área de acesso</h1>\n    <p>Entre com seu usuário para acessar o sistema.</p>\n    <label>Usuário<input id=\"loginUsuario\" autocomplete=\"username\" required></label>\n    <label>Senha<input id=\"loginSenha\" type=\"password\" autocomplete=\"current-password\" required></label>\n    <button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-right-to-bracket\"></i> Entrar</button>\n    <small id=\"loginMsg\" class=\"message\"></small>\n  </form>\n</section>\n\n<div id=\"app\" class=\"app hidden\">\n  <aside class=\"sidebar\">\n    <div class=\"brand\">CellTech <span>Panamby</span></div>\n    <nav>\n      <button class=\"nav-btn active admin-only\" data-page=\"dashboard\"><i class=\"fa-solid fa-chart-line\"></i> Dashboard</button>\n      <button class=\"nav-btn\" data-page=\"venda\"><i class=\"fa-solid fa-cart-shopping\"></i> Nova venda</button>\n      <button class=\"nav-btn\" data-page=\"compra\"><i class=\"fa-solid fa-mobile-screen\"></i> Nova compra</button>\n      <button class=\"nav-btn\" data-page=\"historico\"><i class=\"fa-solid fa-clock-rotate-left\"></i> Histórico</button>\n      <button class=\"nav-btn staff-only\" data-page=\"atendimentos\"><i class=\"fa-solid fa-comments\"></i> Cotações e contatos</button>\n      <button class=\"nav-btn staff-only\" data-page=\"os-notas\"><i class=\"fa-solid fa-file-signature\"></i> OS e recibos</button>\n      <button class=\"nav-btn\" data-page=\"site\"><i class=\"fa-solid fa-globe\"></i> Produtos no site</button>\n      <button class=\"nav-btn\" data-page=\"comissao\"><i class=\"fa-solid fa-percent\"></i> Comissão</button>\n      <button class=\"nav-btn\" data-page=\"pagamentos\"><i class=\"fa-solid fa-money-check-dollar\"></i> Pagamentos</button>\n      <button class=\"nav-btn admin-only\" data-page=\"usuarios\"><i class=\"fa-solid fa-users-gear\"></i> Usuários</button>\n      <button class=\"nav-btn staff-only\" data-page=\"cadastro-revendedor\"><i class=\"fa-solid fa-user-plus\"></i> Revendedores</button>\n      <button class=\"nav-btn reseller-only\" data-page=\"revendedor\" style=\"display:none\"><i class=\"fa-solid fa-tags\"></i> Catálogo de revenda</button>\n    </nav>\n    <button id=\"logoutBtn\" class=\"logout\"><i class=\"fa-solid fa-arrow-right-from-bracket\"></i> Sair</button>\n  </aside>\n\n  <main>\n    <header class=\"topbar\">\n      <button id=\"menuBtn\" class=\"menu-btn\"><i class=\"fa-solid fa-bars\"></i></button>\n      <div><strong id=\"tituloPagina\">Dashboard</strong><span id=\"usuarioLogado\"></span></div>\n      <button id=\"themeToggle\" class=\"theme-toggle\" type=\"button\" aria-label=\"Alternar tema\" title=\"Alternar entre tema claro e escuro\"><i class=\"fa-solid fa-moon\"></i><span>Tema escuro</span></button>\n    </header>\n\n    <section id=\"page-dashboard\" class=\"page active\">\n      <div class=\"dashboard-intro\"><div><span class=\"eyebrow\">Visão geral</span><h1>Resumo do negócio</h1><p>Acompanhe vendas, estoque e rentabilidade em um só lugar.</p></div></div>\n      <div class=\"cards dashboard-cards\">\n        <article class=\"kpi kpi-blue\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-bolt\"></i></div><span>Faturamento hoje</span><strong id=\"kpiFaturamentoHoje\">R$ 0,00</strong><small>Movimentação do dia</small></article>\n        <article class=\"kpi kpi-violet\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-calendar-days\"></i></div><span>Faturamento no mês</span><strong id=\"kpiFaturamentoMes\">R$ 0,00</strong><small>Total do mês atual</small></article>\n        <article class=\"kpi kpi-cyan\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-cart-shopping\"></i></div><span>Vendas no mês</span><strong id=\"kpiVendasMes\">0</strong><small>Negócios concluídos</small></article>\n        <article class=\"kpi kpi-amber\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-tag\"></i></div><span>Ticket médio</span><strong id=\"kpiTicket\">R$ 0,00</strong><small>Média por venda</small></article>\n        <article class=\"kpi kpi-emerald\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-arrow-trend-up\"></i></div><span>Lucro no mês</span><strong id=\"kpiLucroMes\">R$ 0,00</strong><small>Resultado mensal</small></article>\n        <article class=\"kpi kpi-orange\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-mobile-screen-button\"></i></div><span>Aparelhos disponíveis</span><strong id=\"kpiEstoque\">0</strong><small>Unidades em estoque</small></article>\n        <article class=\"kpi kpi-blue\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-vault\"></i></div><span>Investimento em estoque</span><strong id=\"kpiCustoEstoque\">R$ 0,00</strong><small>Total pago nos aparelhos</small></article>\n        <article class=\"kpi kpi-violet\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-bag-shopping\"></i></div><span>Valor de venda do estoque</span><strong id=\"kpiVendaEstoque\">R$ 0,00</strong><small>Potencial de faturamento</small></article>\n        <article class=\"kpi kpi-emerald\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-chart-line\"></i></div><span>Lucro potencial</span><strong id=\"kpiLucroPotencial\">R$ 0,00</strong><small>Ao vender todo o estoque</small></article>\n        <article class=\"kpi kpi-amber\"><div class=\"kpi-icon\"><i class=\"fa-solid fa-chart-pie\"></i></div><span>Margem média</span><strong id=\"kpiMargemMedia\">0%</strong><small>Rentabilidade média</small></article>\n      </div>\n      <div class=\"panel\"><h2>Faturamento dos últimos 30 dias</h2><div class=\"chart-wrap\"><canvas id=\"salesChart\"></canvas></div></div>\n    </section>\n\n    <section id=\"page-venda\" class=\"page\">\n      <div class=\"panel form-panel\">\n        <h2>Cadastrar venda</h2>\n        <form id=\"vendaForm\" class=\"grid-form\">\n          <label>Nome do cliente<input name=\"nome\" required maxlength=\"120\"></label>\n          <label>CPF<input name=\"cpf\" class=\"cpf\" inputmode=\"numeric\" required maxlength=\"14\"></label>\n          <label>Telefone<input name=\"telefone\" inputmode=\"tel\" maxlength=\"20\"></label>\n          <label>Data da venda<input name=\"dataVenda\" type=\"date\" required></label>\n          <label class=\"full\">Aparelho do estoque<select name=\"idEstoque\" id=\"estoqueSelect\" required><option value=\"\">Carregando estoque...</option></select></label>\n          <label>Forma de pagamento<select name=\"formaPagamento\" required><option value=\"\">Selecione</option><option>PIX</option><option>Dinheiro</option><option>Cartão de débito</option><option>Cartão de crédito</option><option>Transferência</option><option>Outro</option></select></label>\n          <label>Valor da venda<input name=\"valorVenda\" class=\"money\" inputmode=\"decimal\" required></label>\n          <label>Garantia da loja (dias)<input name=\"garantiaDias\" type=\"number\" min=\"0\" max=\"3650\" value=\"90\" required></label>\n          <label class=\"full\">Observações<textarea name=\"observacoes\" rows=\"3\" maxlength=\"500\"></textarea></label>\n          <label class=\"full receipt-option\"><input name=\"gerarRecibo\" type=\"checkbox\" checked> Gerar e imprimir recibo após salvar</label>\n          <div class=\"full actions\"><button class=\"primary\" type=\"submit\">Salvar venda e gerar recibo</button><span class=\"message form-message\"></span></div>\n        </form>\n      </div>\n    </section>\n\n    <section id=\"page-compra\" class=\"page\">\n      <div class=\"panel form-panel\">\n        <h2>Cadastrar celular comprado</h2>\n        <form id=\"compraForm\" class=\"grid-form\">\n          <label>Nome de quem vendeu<input name=\"nome\" required maxlength=\"120\"></label>\n          <label>CPF<input name=\"cpf\" class=\"cpf\" inputmode=\"numeric\" required maxlength=\"14\"></label>\n          <label>Telefone<input name=\"telefone\" inputmode=\"tel\" maxlength=\"20\"></label>\n          <label>Data da compra<input name=\"dataCompra\" type=\"date\" required></label>\n          <label>Modelo<input name=\"modelo\" required maxlength=\"120\"></label>\n          <label>Armazenamento<input name=\"armazenamento\" placeholder=\"Ex.: 128 GB\"></label>\n          <label>Cor<input name=\"cor\"></label>\n          <label>IMEI 1<input name=\"imei\" inputmode=\"numeric\" required maxlength=\"15\"></label>\n          <label>IMEI 2<input name=\"imei2\" inputmode=\"numeric\" maxlength=\"15\" placeholder=\"Opcional\"></label>\n          <label>Valor da compra<input name=\"valorCompra\" class=\"money\" inputmode=\"decimal\" required></label>\n          <label>Preço de venda no PIX<input name=\"precoSite\" class=\"money\" inputmode=\"decimal\" required></label>\n          <label>Preço para revendedor<input name=\"precoRevenda\" class=\"money\" inputmode=\"decimal\" required></label>\n          <label>Categoria<select name=\"categoriaSite\"><option value=\"iPhone\">iPhone</option><option value=\"iPad\">iPad</option><option value=\"MacBook\">MacBook</option><option value=\"Apple Watch\">Apple Watch</option><option value=\"Acessório\">Acessório</option></select></label>\n          <label>Condição<input name=\"condicaoSite\" value=\"Seminovo\" maxlength=\"60\"></label>\n          <label>Saúde da bateria<input name=\"bateriaSite\" placeholder=\"Ex.: 89%\" maxlength=\"20\"></label>\n          <label>Publicação<select name=\"statusSite\"><option value=\"Publicado\">Publicar no site</option><option value=\"Oculto\">Cadastrar oculto</option><option value=\"Reservado\">Reservado</option></select></label>\n          <label class=\"full\">Comentário exclusivo para revendedores<textarea name=\"comentarioRevendedor\" rows=\"3\" maxlength=\"600\" placeholder=\"Ex.: Tela original substituída, bateria trocada ou pequeno detalhe estético. Deixe vazio quando não houver observações.\"></textarea><small class=\"field-help\">Este texto não aparece no site público. Ele será exibido somente no catálogo dos revendedores.</small></label>\n          <label class=\"full\">Fotos do produto <span class=\"optional-label\">(opcional)</span><input name=\"fotosProduto\" type=\"file\" accept=\"image/*\" multiple><small class=\"field-help\">Opcional. Você pode enviar até 6 fotos agora ou adicionar depois na edição do produto.</small></label>\n          <label>Forma de pagamento<select name=\"formaPagamento\"><option value=\"\">Selecione</option><option>PIX</option><option>Dinheiro</option><option>Transferência</option><option>Outro</option></select></label>\n          <label class=\"full\">Observações<textarea name=\"observacoes\" rows=\"3\" maxlength=\"500\"></textarea></label>\n          <label class=\"full receipt-option\"><input name=\"gerarRecibo\" type=\"checkbox\" checked> Gerar e imprimir recibo após salvar</label>\n          <div class=\"full actions\"><button class=\"primary\" type=\"submit\">Salvar compra e gerar recibo</button><span class=\"message form-message\"></span></div>\n        </form>\n      </div>\n    </section>\n\n    <section id=\"page-site\" class=\"page\">\n      <div class=\"panel\">\n        <div class=\"panel-head\"><div><h2>Produtos no site</h2><p class=\"commission-note\">Controle quais aparelhos aparecem na página pública.</p></div><button id=\"atualizarSiteProdutos\" class=\"secondary\">Atualizar</button></div>\n        <div class=\"table-wrap products-table-wrap\"><table class=\"products-table\"><thead><tr><th>Foto</th><th>Produto</th><th class=\"col-price\">Preço PIX</th><th class=\"col-resale\">Preço revenda</th><th class=\"col-cost\">Custo</th><th class=\"col-profit\">Lucro</th><th class=\"col-margin\">Margem</th><th>Status</th><th class=\"col-actions\">Ações</th></tr></thead><tbody id=\"siteProdutosBody\"><tr><td colspan=\"9\">Carregando...</td></tr></tbody></table></div>\n        <p id=\"siteProdutosMsg\" class=\"message\"></p>\n      </div>\n    </section>\n\n    <section id=\"page-historico\" class=\"page\">\n      <div class=\"panel\">\n        <div class=\"panel-head\"><div><h2>Histórico</h2><p class=\"history-subtitle\">Últimas compras e vendas aparecem automaticamente. Use os filtros para localizar qualquer movimentação.</p></div><button id=\"buscarHistorico\" class=\"secondary\">Buscar</button></div>\n        <div class=\"filters\">\n          <label>Tipo<select id=\"histTipo\"><option value=\"todos\">Compras e vendas</option><option value=\"vendas\">Somente vendas</option><option value=\"compras\">Somente compras</option></select></label>\n          <label>De<input id=\"histInicio\" type=\"date\"></label>\n          <label>Até<input id=\"histFim\" type=\"date\"></label>\n          <label>Pesquisa<input id=\"histBusca\" placeholder=\"Nome, CPF, modelo ou IMEI\"></label>\n        </div>\n        <div class=\"table-wrap\"><table><thead id=\"histHead\"></thead><tbody id=\"histBody\"></tbody></table></div>\n        <p id=\"histMsg\" class=\"message\"></p>\n      </div>\n    </section>\n\n\n    <section id=\"page-atendimentos\" class=\"page staff-only\">\n      <div class=\"panel leads-panel\">\n        <div class=\"panel-head\"><div><h2>Cotações e contatos do site</h2><p class=\"commission-note\">Veja quem pediu uma avaliação ou manutenção. Abra o WhatsApp, registre o atendimento e acompanhe os resultados.</p></div><button id=\"atualizarAtendimentos\" class=\"secondary\" type=\"button\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n        <div class=\"leads-summary\" id=\"leadsTabs\" role=\"group\" aria-label=\"Filtrar atendimentos\">\n          <button type=\"button\" class=\"lead-tab active\" data-status=\"Novo\" aria-pressed=\"true\"><i class=\"fa-solid fa-inbox\"></i> Novos <strong data-count=\"Novo\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"Em contato\" aria-pressed=\"false\"><i class=\"fa-solid fa-comments\"></i> Em contato <strong data-count=\"Em contato\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"Atendido\" aria-pressed=\"false\"><i class=\"fa-solid fa-user-check\"></i> Atendidos <strong data-count=\"Atendido\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"Celular comprado\" aria-pressed=\"false\"><i class=\"fa-solid fa-mobile-screen-button\"></i> Comprados <strong data-count=\"Celular comprado\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"Oferta recusada\" aria-pressed=\"false\"><i class=\"fa-solid fa-circle-xmark\"></i> Oferta recusada <strong data-count=\"Oferta recusada\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"Serviço finalizado\" aria-pressed=\"false\"><i class=\"fa-solid fa-screwdriver-wrench\"></i> Serviço finalizado <strong data-count=\"Serviço finalizado\">0</strong></button>\n          <button type=\"button\" class=\"lead-tab\" data-status=\"\" aria-pressed=\"false\"><i class=\"fa-solid fa-list\"></i> Todos <strong data-count=\"todos\">0</strong></button>\n        </div>\n        <div class=\"filters leads-filters\">\n          <label>Formulário<select id=\"atendimentosTipo\"><option value=\"\">Cotação e manutenção</option><option value=\"cotacao\">Cotação de iPhone</option><option value=\"manutencao\">Manutenção</option></select></label>\n          <label>Buscar<input id=\"atendimentosBusca\" type=\"search\" placeholder=\"Nome, WhatsApp, modelo ou ID\"></label>\n        </div>\n        <p id=\"atendimentosMsg\" class=\"message\" role=\"status\"></p>\n        <div id=\"atendimentosLista\" class=\"leads-list\"></div>\n      </div>\n    </section>\n\n    <section id=\"page-os-notas\" class=\"page staff-only\">\n      <div class=\"document-center-head\">\n        <div><span class=\"eyebrow\">Atendimento da loja</span><h1>OS e recibos</h1><p>Gere OS de manutenção, recibos simples de acessórios e consulte as OS já emitidas.</p></div>\n      </div>\n\n      <div class=\"doc-tabs\" role=\"tablist\" aria-label=\"OS e recibos\">\n        <button class=\"doc-tab active\" type=\"button\" data-doc-tab=\"nova-os\"><i class=\"fa-solid fa-screwdriver-wrench\"></i><span>Nova OS</span></button>\n        <button class=\"doc-tab\" type=\"button\" data-doc-tab=\"nota-produto\"><i class=\"fa-solid fa-receipt\"></i><span>Recibo de acessório</span></button>\n        <button class=\"doc-tab\" type=\"button\" data-doc-tab=\"manutencoes\"><i class=\"fa-solid fa-mobile-screen-button\"></i><span>Manutenções</span></button>\n        <button class=\"doc-tab\" type=\"button\" data-doc-tab=\"lucro-manutencao\"><i class=\"fa-solid fa-chart-line\"></i><span>Lucro manutenção</span></button>\n        <button class=\"doc-tab\" type=\"button\" data-doc-tab=\"consultar-os\"><i class=\"fa-solid fa-magnifying-glass\"></i><span>Consultar OS</span></button>\n      </div>\n\n      <div id=\"doc-tab-nova-os\" class=\"doc-tab-panel active\">\n        <div class=\"panel form-panel doc-form-panel\">\n          <div class=\"panel-head\"><div><h2>Gerar ordem de serviço</h2><p class=\"commission-note\">Para manutenção de celular, troca de peça ou outro serviço técnico. A OS é emitida sem campo de assinatura.</p></div><div class=\"doc-icon\"><i class=\"fa-solid fa-screwdriver-wrench\"></i></div></div>\n          <form id=\"osForm\" class=\"grid-form\">\n            <label>Nome do cliente<input name=\"nome\" required maxlength=\"120\"></label>\n            <label>CPF <span class=\"optional-label\">(opcional)</span><input name=\"cpf\" class=\"cpf\" inputmode=\"numeric\" maxlength=\"14\"></label>\n            <label>Telefone<input name=\"telefone\" inputmode=\"tel\" maxlength=\"20\"></label>\n            <label>Data da OS<input name=\"dataOS\" type=\"date\" required></label>\n            <label class=\"full\">Aparelho<input name=\"produto\" maxlength=\"160\" placeholder=\"Ex.: iPhone 13 128 GB\"></label>\n            <label class=\"full\">Descrição do serviço<textarea name=\"descricao\" rows=\"5\" required maxlength=\"1200\" placeholder=\"Descreva o serviço realizado, peças trocadas e demais informações importantes.\"></textarea></label>\n            <label>Valor cobrado do cliente<input name=\"valor\" class=\"money\" inputmode=\"decimal\" required placeholder=\"R$ 0,00\"></label>\n            <label>Custo da peça / serviço <span class=\"optional-label\">(interno)</span><input name=\"custoPeca\" class=\"money\" inputmode=\"decimal\" placeholder=\"R$ 0,00\"></label>\n            <label>Forma de pagamento<select name=\"formaPagamento\"><option value=\"\">Selecione</option><option>PIX</option><option>Dinheiro</option><option>Cartão de débito</option><option>Cartão de crédito</option><option>Transferência</option><option>Outro</option></select></label>\n            <label>Status inicial<select name=\"status\"><option selected>Recebido</option><option>Em manutenção</option><option>Aguardando peça</option><option>Pronto para retirada</option><option>Entregue</option></select></label>\n            <label class=\"full\">Observações<textarea name=\"observacoes\" rows=\"3\" maxlength=\"700\" placeholder=\"Opcional\"></textarea></label>\n            <label class=\"full receipt-option\"><input name=\"gerarDocumento\" type=\"checkbox\" checked> Gerar e imprimir a OS após salvar</label>\n            <div class=\"full actions\"><button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-file-circle-check\"></i> Salvar e gerar OS</button><span class=\"message form-message\"></span></div>\n          </form>\n        </div>\n      </div>\n\n      <div id=\"doc-tab-nota-produto\" class=\"doc-tab-panel\">\n        <div class=\"panel form-panel doc-form-panel\">\n          <div class=\"panel-head\"><div><h2>Gerar recibo de acessório</h2><p class=\"commission-note\">Use quando o cliente pedir um comprovante da compra de capa, película, carregador, cabo ou outro acessório. Sem campo de assinatura.</p></div><div class=\"doc-icon\"><i class=\"fa-solid fa-receipt\"></i></div></div>\n          <form id=\"notaProdutoForm\" class=\"grid-form\">\n            <label>Nome do cliente<input name=\"nome\" required maxlength=\"120\"></label>\n            <label>CPF <span class=\"optional-label\">(opcional)</span><input name=\"cpf\" class=\"cpf\" inputmode=\"numeric\" maxlength=\"14\"></label>\n            <label>Telefone<input name=\"telefone\" inputmode=\"tel\" maxlength=\"20\"></label>\n            <label>Data da venda<input name=\"dataVenda\" type=\"date\" required></label>\n            <label class=\"full\">Acessório vendido<input name=\"produto\" required maxlength=\"220\" placeholder=\"Ex.: Carregador USB-C 20W Apple\"></label>\n            <label>Quantidade<input name=\"quantidade\" type=\"number\" min=\"1\" max=\"999\" value=\"1\" required></label>\n            <label>Valor total<input name=\"valor\" class=\"money\" inputmode=\"decimal\" required placeholder=\"R$ 0,00\"></label>\n            <label>Forma de pagamento<select name=\"formaPagamento\"><option value=\"\">Selecione</option><option>PIX</option><option>Dinheiro</option><option>Cartão de débito</option><option>Cartão de crédito</option><option>Transferência</option><option>Outro</option></select></label>\n            <label>Garantia do acessório (dias)<input name=\"garantiaDias\" type=\"number\" min=\"0\" max=\"3650\" value=\"90\"></label>\n            <label class=\"full\">Observações<textarea name=\"observacoes\" rows=\"3\" maxlength=\"700\" placeholder=\"Opcional\"></textarea></label>\n            <label class=\"full receipt-option\"><input name=\"gerarDocumento\" type=\"checkbox\" checked> Gerar e imprimir o recibo após salvar</label>\n            <div class=\"full actions\"><button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-print\"></i> Salvar e gerar recibo</button><span class=\"message form-message\"></span></div>\n          </form>\n        </div>\n      </div>\n\n\n      <div id=\"doc-tab-manutencoes\" class=\"doc-tab-panel\">\n        <div class=\"maintenance-summary\">\n          <article class=\"maintenance-stat\"><span>Recebidos</span><strong id=\"osCountRecebido\">0</strong></article>\n          <article class=\"maintenance-stat\"><span>Em manutenção</span><strong id=\"osCountManutencao\">0</strong></article>\n          <article class=\"maintenance-stat\"><span>Aguardando peça</span><strong id=\"osCountPeca\">0</strong></article>\n          <article class=\"maintenance-stat\"><span>Prontos</span><strong id=\"osCountPronto\">0</strong></article>\n          <article class=\"maintenance-stat\"><span>Entregues</span><strong id=\"osCountEntregue\">0</strong></article>\n        </div>\n        <div class=\"panel os-search-panel maintenance-panel\">\n          <div class=\"panel-head\"><div><h2>Acompanhamento das manutenções</h2><p class=\"commission-note\">Acompanhe todos os aparelhos e altere o andamento da OS conforme o serviço avança.</p></div><button id=\"atualizarManutencoes\" class=\"secondary\" type=\"button\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n          <div class=\"filters maintenance-filters\">\n            <label>Status<select id=\"manutencaoStatus\"><option value=\"ativos\" selected>Em andamento</option><option value=\"\">Todos</option><option>Recebido</option><option>Em manutenção</option><option>Aguardando peça</option><option>Pronto para retirada</option><option>Entregue</option></select></label>\n            <label class=\"os-search-input\">Pesquisa<input id=\"manutencaoBusca\" type=\"search\" placeholder=\"Cliente, telefone, aparelho ou nº OS\"></label>\n          </div>\n          <div class=\"table-wrap os-table-wrap\"><table class=\"os-table maintenance-table\"><thead><tr><th>Nº OS</th><th>Entrada</th><th>Cliente</th><th>Aparelho</th><th>Serviço</th><th>Valor cliente</th><th>Custo interno</th><th>Lucro</th><th>Status</th><th>Última atualização</th><th>Ações</th></tr></thead><tbody id=\"manutencaoBody\"><tr><td colspan=\"11\">Carregando manutenções...</td></tr></tbody></table></div>\n          <p id=\"manutencaoMsg\" class=\"message\"></p>\n        </div>\n      </div>\n\n      <div id=\"doc-tab-lucro-manutencao\" class=\"doc-tab-panel\">\n        <div class=\"maintenance-profit-summary\">\n          <article class=\"profit-kpi\"><span>Faturamento</span><strong id=\"lucroOSFaturamento\">R$ 0,00</strong><small>Valor cobrado nas OS filtradas</small></article>\n          <article class=\"profit-kpi\"><span>Custo informado</span><strong id=\"lucroOSCusto\">R$ 0,00</strong><small>Peças e serviços já cadastrados</small></article>\n          <article class=\"profit-kpi highlight\"><span>Lucro apurado</span><strong id=\"lucroOSLucro\">R$ 0,00</strong><small>Somente OS com custo informado</small></article>\n          <article class=\"profit-kpi\"><span>Margem apurada</span><strong id=\"lucroOSMargem\">0%</strong><small>Sobre OS com custo informado</small></article>\n          <article class=\"profit-kpi warning\"><span>Custo pendente</span><strong id=\"lucroOSPendente\">0</strong><small>OS que ainda precisam do custo</small></article>\n        </div>\n        <div class=\"panel os-search-panel profit-panel\">\n          <div class=\"panel-head\"><div><h2>Painel de lucro das manutenções</h2><p class=\"commission-note\">Acompanhe faturamento, custo e lucro por período. OS sem custo ficam sinalizadas como pendentes para não distorcer o resultado.</p></div><button id=\"atualizarLucroOS\" class=\"secondary\" type=\"button\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n          <div class=\"filters profit-filters\">\n            <label>De<input id=\"lucroOSInicio\" type=\"date\"></label>\n            <label>Até<input id=\"lucroOSFim\" type=\"date\"></label>\n            <label>Status<select id=\"lucroOSStatus\"><option value=\"\">Todos</option><option>Recebido</option><option>Em manutenção</option><option>Aguardando peça</option><option>Pronto para retirada</option><option>Entregue</option></select></label>\n          </div>\n          <div class=\"profit-notice\"><i class=\"fa-solid fa-circle-info\"></i><span>O lucro só é considerado apurado quando o custo da peça/serviço foi preenchido.</span></div>\n          <div class=\"table-wrap os-table-wrap\"><table class=\"os-table profit-table\"><thead><tr><th>Nº OS</th><th>Data</th><th>Cliente</th><th>Aparelho</th><th>Status</th><th>Valor cliente</th><th>Custo</th><th>Lucro</th><th>Margem</th></tr></thead><tbody id=\"lucroOSBody\"><tr><td colspan=\"9\">Carregando painel...</td></tr></tbody></table></div>\n          <p id=\"lucroOSMsg\" class=\"message\"></p>\n        </div>\n      </div>\n\n      <div id=\"doc-tab-consultar-os\" class=\"doc-tab-panel\">\n        <div class=\"panel os-search-panel\">\n          <div class=\"panel-head\"><div><h2>Consultar ordens de serviço</h2><p class=\"commission-note\">Pesquise por número da OS, cliente, telefone, aparelho ou descrição do serviço.</p></div><button id=\"buscarOS\" class=\"secondary\" type=\"button\"><i class=\"fa-solid fa-magnifying-glass\"></i> Buscar</button></div>\n          <div class=\"filters os-filters\">\n            <label>De<input id=\"osInicio\" type=\"date\"></label>\n            <label>Até<input id=\"osFim\" type=\"date\"></label>\n            <label class=\"os-search-input\">Pesquisa<input id=\"osBusca\" type=\"search\" placeholder=\"Nº OS, cliente, telefone ou serviço\"></label>\n          </div>\n          <div class=\"table-wrap os-table-wrap\"><table class=\"os-table\"><thead><tr><th>Nº OS</th><th>Data</th><th>Cliente</th><th>Aparelho / produto</th><th>Serviço</th><th>Status</th><th>Valor cliente</th><th>Custo interno</th><th>Lucro</th><th>Funcionário</th><th>Ações</th></tr></thead><tbody id=\"osBody\"><tr><td colspan=\"11\">Clique em Buscar para consultar.</td></tr></tbody></table></div>\n          <p id=\"osMsg\" class=\"message\"></p>\n        </div>\n      </div>\n    </section>\n\n\n    <section id=\"page-comissao\" class=\"page\">\n      <div class=\"panel commission-overview-panel\">\n        <div class=\"panel-head\">\n          <div class=\"admin-only\">\n            <span class=\"eyebrow\">Comissão compartilhada</span>\n            <h2>Histórico de vendas e aprovação</h2>\n            <p class=\"commission-note\">Todas as vendas da loja aparecem aqui. Aprove ou negue a comissão de cada venda; ao aprovar, a venda passa a gerar <strong>2% para cada funcionário elegível</strong>.</p>\n          </div>\n          <div class=\"worker-only worker-finance-heading\">\n            <span class=\"eyebrow\">Minhas comissões</span>\n            <h2>Comissão</h2>\n            <p class=\"commission-note\">Veja suas comissões aprovadas, pendentes e o histórico de cada venda.</p>\n          </div>\n          <button id=\"buscarComissao\" class=\"secondary\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button>\n        </div>\n        <div class=\"filters commission-filter\">\n          <label>Mês de referência<input id=\"comissaoMes\" type=\"month\"></label>\n        </div>\n      </div>\n\n      <div class=\"cards commission-cards admin-only\">\n        <article><span>Vendas no mês</span><strong id=\"commissionSalesTotal\">0</strong></article>\n        <article><span>Pendentes</span><strong id=\"commissionSalesPending\">0</strong></article>\n        <article><span>Aprovadas</span><strong id=\"commissionSalesApproved\">0</strong></article>\n        <article><span>Negadas</span><strong id=\"commissionSalesRejected\">0</strong></article>\n      </div>\n\n      <div class=\"cards commission-cards worker-only worker-commission-summary\">\n        <article class=\"worker-money-card commission worker-commission-summary-card approved-card\">\n          <div class=\"worker-card-icon\"><i class=\"fa-solid fa-circle-check\"></i></div>\n          <span>Comissões aprovadas a receber</span>\n          <strong id=\"workerComissao\">R$ 0,00</strong>\n          <small>Vendas aprovadas pelo administrador • 2% por venda elegível</small>\n        </article>\n        <article class=\"worker-money-card pending-commission worker-commission-summary-card pending-card\">\n          <div class=\"worker-card-icon\"><i class=\"fa-solid fa-clock\"></i></div>\n          <span>Comissões pendentes</span>\n          <strong id=\"workerComissaoPendente\">R$ 0,00</strong>\n          <small id=\"workerComissaoPendenteInfo\">Aguardando análise do administrador</small>\n        </article>\n      </div>\n      <div class=\"panel worker-only worker-commission-info-panel\">\n        <div class=\"worker-commission-info-copy\">\n          <i class=\"fa-solid fa-circle-info\"></i>\n          <div><strong>Como funciona</strong><p>As vendas elegíveis aparecem abaixo mesmo antes da aprovação. Vendas anteriores ao seu cadastro continuam no histórico, mas ficam marcadas como sem direito à comissão.</p></div>\n        </div>\n        <p id=\"workerCommissionMsg\" class=\"message\"></p>\n      </div>\n\n      <div class=\"panel worker-only worker-commission-history-panel\">\n        <div class=\"panel-head\"><div><h2>Histórico de comissões</h2><p class=\"commission-note\">Acompanhe cada venda e veja se sua comissão está pendente, aprovada, negada ou se a venda ocorreu antes do seu cadastro.</p></div></div>\n        <div class=\"table-wrap\">\n          <table class=\"worker-commission-history-table\">\n            <thead><tr><th>Data</th><th>Cliente</th><th>Aparelho</th><th>Valor da venda</th><th>Status</th><th>Minha situação</th><th>Minha comissão</th></tr></thead>\n            <tbody id=\"workerCommissionSalesBody\"><tr><td colspan=\"7\">Selecione o mês para carregar.</td></tr></tbody>\n          </table>\n        </div>\n      </div>\n\n      <div class=\"panel commission-sales-panel admin-only\">\n        <div class=\"panel-head\"><div><h2>Vendas da loja</h2><p class=\"commission-note\">O status é único para a venda e vale para toda a equipe.</p></div></div>\n        <div class=\"table-wrap\">\n          <table class=\"commission-sales-table\">\n            <thead><tr><th>Data</th><th>Cliente</th><th>Aparelho</th><th>Valor</th><th>Responsável</th><th>Status da comissão</th><th>Ação</th></tr></thead>\n            <tbody id=\"commissionSalesBody\"><tr><td colspan=\"7\">Selecione o mês para carregar.</td></tr></tbody>\n          </table>\n        </div>\n        <p id=\"comissaoMsg\" class=\"message\"></p>\n      </div>\n    </section>\n\n    <section id=\"page-pagamentos\" class=\"page\">\n      <div class=\"panel commission-overview-panel\">\n        <div class=\"panel-head\">\n          <div class=\"admin-only\">\n            <span class=\"eyebrow\">Financeiro da equipe</span>\n            <h2>Pagamentos</h2>\n            <p class=\"commission-note\">Controle salário, vale-refeição, comissões aprovadas, chave Pix e baixas de pagamento.</p>\n          </div>\n          <div class=\"worker-only worker-finance-heading\">\n            <span class=\"eyebrow\">Meu financeiro</span>\n            <h2>Pagamentos</h2>\n            <p class=\"commission-note\">Acompanhe salário, vale-refeição, comissão, total a receber, chave Pix, próxima data de pagamento e solicitações de vale.</p>\n          </div>\n          <button id=\"buscarPagamentos\" class=\"secondary\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button>\n        </div>\n        <div class=\"filters commission-filter\">\n          <label>Mês de referência<input id=\"pagamentosMes\" type=\"month\"></label>\n        </div>\n      </div>\n\n      <div class=\"cards commission-cards worker-only worker-money-cards\">\n        <article class=\"worker-money-card salary\"><div class=\"worker-card-icon\"><i class=\"fa-solid fa-wallet\"></i></div><span>Saldo de salário</span><strong id=\"workerSalario\">R$ 0,00</strong><small>Já considera os vales solicitados no período</small></article>\n        <article class=\"worker-money-card meal\"><div class=\"worker-card-icon\"><i class=\"fa-solid fa-utensils\"></i></div><span>Meu vale-refeição</span><strong id=\"workerVale\">R$ 0,00</strong><small>Valor previsto para o mês</small></article>\n        <article class=\"worker-money-card commission\"><div class=\"worker-card-icon\"><i class=\"fa-solid fa-percent\"></i></div><span>Comissão a receber</span><strong id=\"workerPagamentoComissao\">R$ 0,00</strong><small>Somente vendas aprovadas • 2%</small></article>\n        <article class=\"worker-money-card total\"><div class=\"worker-card-icon\"><i class=\"fa-solid fa-sack-dollar\"></i></div><span>Total a receber</span><strong id=\"workerTotal\">R$ 0,00</strong><small>Salário + VR + comissão</small></article>\n      </div>\n\n      <div class=\"panel worker-only worker-payment-info-panel\">\n        <div class=\"panel-head\">\n          <div><span class=\"eyebrow\">Informações do pagamento</span><h2>Meu próximo pagamento</h2><p class=\"commission-note\">Os valores são atualizados automaticamente conforme o período e as aprovações do administrador.</p></div>\n        </div>\n        <div class=\"worker-payment-info-grid\">\n          <div class=\"worker-payment-info-item\"><span>Pagamento previsto</span><strong id=\"workerPagamentoData\">—</strong><small>5º dia útil do mês seguinte</small></div>\n          <div class=\"worker-payment-info-item status\"><span>Status dos pagamentos</span><div id=\"workerPagamentoStatus\" class=\"payment-statuses\"><span class=\"muted\">Carregando...</span></div></div>\n        </div>\n        <p id=\"workerFinanceMsg\" class=\"message\"></p>\n      </div>\n\n      <div id=\"pixPanel\" class=\"panel worker-only pix-panel\">\n        <div class=\"panel-head\"><div><h2>Minha chave Pix</h2><p class=\"commission-note\">Esta é a chave usada para seus pagamentos.</p></div></div>\n        <div id=\"pixSavedView\" class=\"pix-saved hidden\">\n          <div class=\"pix-saved-icon\"><i class=\"fa-brands fa-pix\"></i></div>\n          <div class=\"pix-saved-copy\"><small>Chave cadastrada • <span id=\"pixSavedType\">Tipo não informado</span></small><strong id=\"pixSavedValue\">—</strong></div>\n          <button id=\"editarPix\" class=\"secondary compact\" type=\"button\"><i class=\"fa-solid fa-pen\"></i> Alterar</button>\n        </div>\n        <form id=\"pixForm\" class=\"pix-form pix-form-with-type\">\n          <label>Tipo da chave Pix<select id=\"tipoMeuPix\" name=\"tipoChavePix\" required><option value=\"\">Selecione</option><option value=\"Telefone\">Telefone</option><option value=\"E-mail\">E-mail</option><option value=\"CPF/CNPJ\">CPF/CNPJ</option><option value=\"Chave aleatória\">Chave aleatória</option></select></label>\n          <label>Chave Pix<input id=\"meuPix\" name=\"chavePix\" placeholder=\"Digite a chave Pix\" required></label>\n          <button class=\"primary\" type=\"submit\"><i class=\"fa-brands fa-pix\"></i> <span id=\"pixSubmitText\">Cadastrar chave Pix</span></button>\n          <button id=\"cancelarPix\" class=\"secondary hidden\" type=\"button\">Cancelar</button>\n          <span id=\"pixMsg\" class=\"message\"></span>\n        </form>\n      </div>\n\n      <div class=\"panel worker-only advance-panel\">\n        <div class=\"advance-callout\">\n          <div class=\"advance-callout-icon\"><i class=\"fa-solid fa-hand-holding-dollar\"></i></div>\n          <div><span class=\"eyebrow\">Adiantamento salarial</span><h2>Precisa de um vale?</h2><p>Se precisar antecipar um valor antes do pagamento, envie uma solicitação aqui. O pedido ficará pendente para análise do administrador e já será considerado no seu saldo até a decisão.</p></div>\n          <button id=\"abrirVale\" class=\"advance-request-btn\" type=\"button\"><i class=\"fa-solid fa-plus\"></i> Pedir vale</button>\n        </div>\n        <form id=\"valeForm\" class=\"advance-form hidden\">\n          <label>Valor do vale<input id=\"valorVale\" name=\"valor\" class=\"money\" inputmode=\"decimal\" placeholder=\"R$ 0,00\" required><small class=\"field-help\">Você pode solicitar o valor que precisar. A solicitação ficará pendente até a análise do administrador.</small></label>\n          <label>Motivo <span class=\"optional-label\">opcional</span><input id=\"motivoVale\" name=\"motivo\" maxlength=\"180\" placeholder=\"Ex.: emergência, transporte, despesa inesperada\"></label>\n          <div class=\"advance-form-actions\"><button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-paper-plane\"></i> Enviar solicitação</button><button id=\"cancelarVale\" class=\"secondary\" type=\"button\">Cancelar</button></div>\n          <span id=\"valeMsg\" class=\"message\"></span>\n        </form>\n        <div class=\"advance-history-head\"><div><h3>Histórico de vales</h3><p>Acompanhe suas solicitações e o status de cada uma.</p></div><span id=\"valeSaldoDisponivel\" class=\"advance-available\">Saldo de salário atual: R$ 0,00</span></div>\n        <div class=\"table-wrap\"><table class=\"advance-table\"><thead><tr><th>Data</th><th>Valor</th><th>Motivo</th><th>Status</th><th>Decisão</th></tr></thead><tbody id=\"workerValesBody\"><tr><td colspan=\"5\">Nenhum vale solicitado.</td></tr></tbody></table></div>\n      </div>\n\n      <div class=\"cards commission-cards payroll-cards admin-only\">\n        <article><span>Salários do mês</span><strong id=\"financeSalario\">R$ 0,00</strong></article>\n        <article><span>Vale-refeição do mês</span><strong id=\"financeVale\">R$ 0,00</strong></article>\n        <article><span>Comissões aprovadas</span><strong id=\"financeComissao\">R$ 0,00</strong></article>\n        <article><span>Total a pagar</span><strong id=\"financeTotal\">R$ 0,00</strong></article>\n        <article><span>Vendas aprovadas no mês</span><strong id=\"financeVendas\">0</strong></article>\n        <article><span>Pagamento previsto</span><strong id=\"financeVencimento\">—</strong></article>\n      </div>\n\n      <div class=\"panel payroll-panel admin-only\">\n        <div class=\"panel-head\"><div><h2>Pagamento da equipe</h2><p class=\"commission-note\">A comissão abaixo considera somente vendas aprovadas e ocorridas depois do cadastro de cada funcionário.</p></div></div>\n        <div class=\"table-wrap\">\n          <table class=\"payroll-table\">\n            <thead><tr><th>Funcionário</th><th>Salário mensal</th><th>Vale-refeição</th><th>Comissão 2%</th><th>Total a pagar</th><th>Pagamento</th><th>Chave Pix</th><th>Pagamentos</th><th>Ações</th></tr></thead>\n            <tbody id=\"pagamentosBody\"><tr><td colspan=\"9\">Selecione o mês para carregar.</td></tr></tbody>\n          </table>\n        </div>\n        <p id=\"pagamentosMsg\" class=\"message\"></p>\n      </div>\n\n      <div class=\"panel advance-admin-panel admin-only\">\n        <div class=\"panel-head\"><div><span class=\"eyebrow\">Adiantamentos</span><h2>Solicitações de vale</h2><p class=\"commission-note\">Ao aprovar, o vale é registrado como pago e descontado automaticamente do salário disponível do funcionário.</p></div><button id=\"atualizarValesAdmin\" class=\"secondary compact\" type=\"button\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n        <div class=\"advance-admin-summary\"><span><b id=\"valesPendentesAdmin\">0</b> pendentes</span><span><b id=\"valesAprovadosAdmin\">R$ 0,00</b> aprovados/pagos</span></div>\n        <div class=\"table-wrap\"><table class=\"advance-table admin\"><thead><tr><th>Solicitado em</th><th>Funcionário</th><th>Valor</th><th>Motivo</th><th>Status</th><th>Decisão</th><th>Ações</th></tr></thead><tbody id=\"adminValesBody\"><tr><td colspan=\"7\">Selecione o mês para carregar.</td></tr></tbody></table></div>\n        <p id=\"adminValesMsg\" class=\"message\"></p>\n      </div>\n    </section>\n\n    <section id=\"page-cadastro-revendedor\" class=\"page staff-only\">\n      <div class=\"panel form-panel reseller-register-panel\">\n        <div class=\"panel-head\">\n          <div>\n            <span class=\"eyebrow\">Parceiros</span>\n            <h2>Cadastrar novo revendedor</h2>\n            <p class=\"commission-note\">Funcionários e administradores podem criar acessos de revendedor. Para confirmar o cadastro, o sistema pedirá a sua própria senha.</p>\n          </div>\n        </div>\n        <form id=\"revendedorForm\" class=\"grid-form\">\n          <label>Nome do revendedor<input name=\"nome\" required maxlength=\"120\"></label>\n          <label>Usuário de acesso<input name=\"usuario\" required minlength=\"3\" maxlength=\"60\" autocomplete=\"off\"></label>\n          <label>Senha inicial<input name=\"senha\" type=\"password\" required minlength=\"6\" autocomplete=\"new-password\"><small>Mínimo de 6 caracteres.</small></label>\n          <div class=\"full actions\"><button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-user-plus\"></i> Cadastrar revendedor</button><span class=\"message form-message\"></span></div>\n        </form>\n      </div>\n      <div class=\"panel table-panel\">\n        <div class=\"panel-head\"><div><h2>Revendedores cadastrados</h2><p class=\"commission-note\">Lista de parceiros com acesso ao catálogo exclusivo.</p></div><button type=\"button\" class=\"secondary\" id=\"atualizarRevendedores\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n        <div class=\"table-wrap\"><table class=\"reseller-users-table\"><thead><tr><th>Nome</th><th>Usuário</th><th>Status</th><th>Cadastro</th></tr></thead><tbody id=\"revendedoresBody\"><tr><td colspan=\"4\">Carregando...</td></tr></tbody></table></div>\n        <p id=\"revendedoresMsg\" class=\"message\"></p>\n      </div>\n    </section>\n\n    <section id=\"page-revendedor\" class=\"page reseller-only\">\n      <div class=\"reseller-hero\">\n        <div><span>PARCERIA PARA QUEM QUER LUCRAR</span><h1>Catálogo exclusivo para revendedores</h1><p>Aparelhos selecionados, valores especiais e informações transparentes para você comprar com segurança e aumentar sua margem.</p></div>\n        <div class=\"reseller-hero-badge\"><i class=\"fa-solid fa-handshake\"></i><strong>Condições exclusivas</strong><small>Preço especial para parceiros</small></div>\n      </div>\n      <div class=\"reseller-highlight-strip\">\n        <div><i class=\"fa-solid fa-circle-check\"></i><span><strong>Estoque real</strong><small>Somente aparelhos disponíveis</small></span></div>\n        <div><i class=\"fa-solid fa-camera\"></i><span><strong>Fotos reais</strong><small>Veja o produto antes de comprar</small></span></div>\n        <div><i class=\"fa-solid fa-bolt\"></i><span><strong>Atendimento rápido</strong><small>Negociação direta pelo WhatsApp</small></span></div>\n      </div>\n      <div class=\"reseller-benefits\">\n        <article><i class=\"fa-solid fa-shield-halved\"></i><div><strong>Procedência e transparência</strong><p>Informamos o estado do aparelho e qualquer peça substituída antes da compra.</p></div></article>\n        <article><i class=\"fa-solid fa-tags\"></i><div><strong>Preços abaixo do mercado</strong><p>Compare o valor do site com o preço exclusivo e veja sua oportunidade de margem.</p></div></article>\n        <article><i class=\"fa-solid fa-mobile-screen-button\"></i><div><strong>Aparelhos selecionados</strong><p>Produtos avaliados e apresentados com fotos reais e informações completas.</p></div></article>\n        <article><i class=\"fa-solid fa-arrows-rotate\"></i><div><strong>Estoque sempre atualizado</strong><p>Novas oportunidades entram no catálogo conforme os aparelhos ficam disponíveis.</p></div></article>\n      </div>\n      <div class=\"reseller-section-head\"><div><span>OPORTUNIDADES DISPONÍVEIS</span><h2>Escolha os produtos para sua revenda</h2></div><p>Os valores em verde são exclusivos para parceiros cadastrados.</p></div>\n      <div class=\"reseller-toolbar\">\n        <div class=\"reseller-search\"><i class=\"fa-solid fa-magnifying-glass\"></i><input id=\"buscaModeloRevendedor\" type=\"search\" placeholder=\"Pesquisar modelo, armazenamento ou cor\"><button id=\"limparBuscaRevendedor\" type=\"button\" aria-label=\"Limpar busca\"><i class=\"fa-solid fa-xmark\"></i></button></div>\n        <div class=\"reseller-filters\">\n          <select id=\"ordemRevendedor\" aria-label=\"Ordenar produtos\"><option value=\"recentes\">Mais recentes</option><option value=\"menor\">Menor preço</option><option value=\"maior-desconto\">Maior desconto</option><option value=\"modelo\">Modelo A–Z</option></select>\n        </div>\n      </div>\n      <div class=\"reseller-results\"><strong id=\"contadorRevendedor\">0 produtos</strong><span>Estoque atualizado para parceiros</span></div>\n      <div id=\"revendedorCatalogo\" class=\"reseller-grid\"><div class=\"panel\">Carregando produtos...</div></div>\n      <section class=\"reseller-how\">\n        <div class=\"reseller-how-head\"><span>COMPRA SIMPLES E SEGURA</span><h2>Como funciona para o revendedor</h2><p>Escolha o aparelho, confira todas as informações e fale direto com nossa equipe.</p></div>\n        <div class=\"reseller-steps\">\n          <article><b>1</b><div><strong>Escolha o aparelho</strong><p>Use a busca e compare os preços disponíveis.</p></div></article>\n          <article><b>2</b><div><strong>Confira os detalhes</strong><p>Veja fotos, bateria, condição e observações importantes.</p></div></article>\n          <article><b>3</b><div><strong>Chame no WhatsApp</strong><p>O produto e o valor já seguem preenchidos na mensagem.</p></div></article>\n        </div>\n      </section>\n      <div class=\"reseller-trust\">\n        <div class=\"reseller-trust-icon\"><i class=\"fa-solid fa-shield-heart\"></i></div>\n        <div><span>NOSSO COMPROMISSO</span><strong>Compra clara, sem surpresa.</strong><p>Qualquer troca de peça ou detalhe importante aparece destacado no próprio anúncio antes da negociação.</p></div>\n        <div class=\"reseller-trust-seal\"><i class=\"fa-solid fa-award\"></i><small>Parceiro<br>DG iPhones</small></div>\n      </div>\n      <p id=\"revendedorMsg\" class=\"message\"></p>\n    </section>\n\n    <section id=\"page-usuarios\" class=\"page admin-only\">\n      <div class=\"panel form-panel\">\n        <div class=\"panel-head\"><div><h2 id=\"usuarioFormTitulo\">Cadastrar funcionário</h2><p class=\"commission-note\">Defina o salário mensal e o perfil de cada integrante da equipe.</p></div></div>\n        <form id=\"usuarioForm\" class=\"grid-form\">\n          <input type=\"hidden\" name=\"idFuncionario\">\n          <label>Nome<input name=\"nome\" required></label>\n          <label>Usuário<input name=\"usuario\" required></label>\n          <label>Senha<input name=\"senha\" type=\"password\" minlength=\"6\" required><small id=\"senhaAjuda\">Mínimo de 6 caracteres.</small></label>\n          <label>Perfil<select name=\"perfil\"><option value=\"Vendedora\">Vendedora</option><option value=\"Técnico\">Técnico</option><option value=\"Funcionário\">Funcionário</option><option value=\"Revendedor\">Revendedor</option><option value=\"Administrador\">Administrador</option></select></label>\n          <label>Salário mensal<input name=\"salario\" class=\"money\" inputmode=\"decimal\" placeholder=\"R$ 0,00\" required></label>\n          <label>Vale-refeição por dia<input name=\"valeRefeicaoDia\" class=\"money\" inputmode=\"decimal\" placeholder=\"R$ 0,00\"><small>O sistema multiplica este valor pelos dias previstos de trabalho.</small></label>\n          <label>Jornada semanal<select name=\"diasSemana\"><option value=\"6\">Segunda a sábado (6 dias)</option><option value=\"5\">Segunda a sexta (5 dias)</option></select></label>\n          <label>Status<select name=\"status\"><option value=\"Ativo\">Ativo</option><option value=\"Inativo\">Inativo</option></select></label>\n          <div class=\"full actions\"><button class=\"primary\" id=\"salvarFuncionarioBtn\">Cadastrar funcionário</button><button type=\"button\" class=\"secondary hidden\" id=\"cancelarEdicaoFuncionario\">Cancelar edição</button><span class=\"message form-message\"></span></div>\n        </form>\n      </div>\n      <div class=\"panel table-panel users-list-panel\">\n        <div class=\"panel-head\"><div><h2>Funcionários cadastrados</h2><p class=\"commission-note\">Salário e chave Pix ficam disponíveis no controle de pagamentos.</p></div><button type=\"button\" class=\"secondary\" id=\"atualizarFuncionarios\"><i class=\"fa-solid fa-rotate\"></i> Atualizar</button></div>\n        <div class=\"table-wrap\"><table><thead><tr><th>Nome</th><th>Usuário</th><th>Perfil</th><th>Salário</th><th>VR/dia</th><th>Jornada</th><th>Cadastro</th><th>Chave Pix</th><th>Status</th><th>Ações</th></tr></thead><tbody id=\"funcionariosBody\"><tr><td colspan=\"10\">Carregando...</td></tr></tbody></table></div>\n        <p id=\"funcionariosMsg\" class=\"message\"></p>\n      </div>\n    </section>\n  </main>\n</div>\n\n<div id=\"confirmPasswordModal\" class=\"confirm-password-modal hidden\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"confirmPasswordTitle\">\n  <div class=\"confirm-password-card\">\n    <div class=\"confirm-password-icon\"><i class=\"fa-solid fa-shield-halved\"></i></div>\n    <div class=\"confirm-password-head\">\n      <span class=\"eyebrow\">Confirmação de segurança</span>\n      <h2 id=\"confirmPasswordTitle\">Confirme sua senha</h2>\n      <p id=\"confirmPasswordAction\">Digite a senha do usuário que está logado para continuar.</p>\n    </div>\n    <form id=\"confirmPasswordForm\">\n      <label>Sua senha<input id=\"confirmPasswordInput\" type=\"password\" autocomplete=\"current-password\" required></label>\n      <small id=\"confirmPasswordError\" class=\"message\"></small>\n      <div class=\"confirm-password-actions\">\n        <button id=\"cancelConfirmPassword\" class=\"secondary\" type=\"button\">Cancelar</button>\n        <button class=\"primary\" type=\"submit\"><i class=\"fa-solid fa-check\"></i> Confirmar operação</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<div id=\"toast\" class=\"toast\"></div>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js\"></script>\n<script src=\"funcionario.js?v=20261006-pagamento-dia-util\"></script>\n<script src=\"atendimentos.js?v=20260929-leads3\"></script>\n</body>\n</html>\n";
module.exports=async(req,res)=>{
  res.setHeader('Cache-Control','private, no-store');
  res.setHeader('X-Robots-Tag','noindex, nofollow, noarchive');
  res.setHeader('X-Content-Type-Options','nosniff');
  res.setHeader('X-Frame-Options','DENY');
  if(req.method!=='GET'&&req.method!=='HEAD')return res.status(405).end();
  try{
    const {user}=await authenticate(req);
    if(!['administrador','funcionario','vendedora','tecnico','revendedor'].includes(require('../lib/common').normal(user.perfil)))return res.status(403).end('Acesso negado.');
  }catch{
    res.setHeader('Location','/funcionario.html');
    return res.status(303).end();
  }
  res.setHeader('Content-Type','text/html; charset=utf-8');
  return res.status(200).end(req.method==='HEAD'?'':HTML);
};
